  tile.innerHTML=ht`<div class="scene" aria-label="Taller de ${esc(project.name)}"></div><div class="island-caption"><button class="project-button" title="Retomar ${esc(project.name)}">${esc(project.name)}${icon('arrow')}</button><button class="new-agent" title="Añadir agente a ${esc(project.name)}" aria-label="Añadir agente a ${esc(project.name)}">${icon('plus')}</button></div><div class="island-agents"></div>`;
  $('#world').append(tile);
  tile.querySelector('.project-button').onclick=()=>openProjectBrief(project.id);
  tile.querySelector('.new-agent').onclick=()=>launchDialog(project.id);
