// Islands' own assistant never writes to an agent terminal.
var aiRequestID=0,aiPending=false,aiError=false,aiResults=new Map();
var aiRequestedAgent=null,checkpointStore=loadCheckpointStore(),checkpointSignature='';
function checkpointKey(a){const project=state.projects.find(p=>p.id===a.projectId);return JSON.stringify([a.profileId || a.harness,project?.path || a.projectId,a.threadId || a.id])}
function loadCheckpointStore(){
 try{const value=JSON.parse(localStorage.getItem('islands.productCheckpoints.v1') || '{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}
}
function agentCheckpoints(a){const identity=checkpointKey(a);let rows=checkpointStore?.[identity];if(!rows&&a.threadId&&checkpointStore){const project=state.projects.find(p=>p.id===a.projectId),old=JSON.stringify([a.profileId||a.harness,project?.path||a.projectId,a.id]);if(checkpointStore[old]){rows=checkpointStore[old];checkpointStore[identity]=rows;if(native)send('checkpoints',{key:identity,entries:rows})}}return Array.isArray(rows)?rows.filter(r=>r&&typeof r.summary==='string'&&Number.isFinite(r.generatedAt)&&Array.isArray(r.changes)).slice(0,20):[]}
function recordCheckpoint(data){
 if(data.error||!data.agentId||!['checkpoint','status','recap','unblock'].includes(data.kind)||!data.summary?.trim())return;
 const a=state.agents.find(a=>a.id===data.agentId);if(!a)return;
 const key=checkpointKey(a),rows=agentCheckpoints(a),entry={summary:String(data.summary).slice(0,6000),headline:String(data.headline || I18n.t('Avance del producto')).slice(0,200),changes:(Array.isArray(data.changes)?data.changes:[]).filter(c=>typeof c==='string'&&c.trim()).slice(0,5).map(c=>c.slice(0,600)),nextStep:String(data.nextStep || '').slice(0,1000),generatedAt:data.generatedAt || Date.now()/1000,capturedAt:data.capturedAt || data.generatedAt || Date.now()/1000,source:String(data.source || I18n.t('Islands')).slice(0,200),taskAt:data.taskAt ?? Math.min(a.taskAt||0,data.capturedAt||data.generatedAt||0),evidence:Array.isArray(data.evidence)?data.evidence:[]};
 checkpointStore[key]=[entry,...rows.filter(r=>r.generatedAt!==entry.generatedAt)].slice(0,20);
 const keys=Object.keys(checkpointStore).sort((a,b)=>(checkpointStore[b]?.[0]?.generatedAt || 0)-(checkpointStore[a]?.[0]?.generatedAt || 0));
 for(const old of keys.slice(100))delete checkpointStore[old];
 try{localStorage.setItem('islands.productCheckpoints.v1',JSON.stringify(checkpointStore))}catch{}
 if(native)send('checkpoints',{key,entries:checkpointStore[key]});
}
function statusLabelSafe(status){return ({passed:'comprobaciones correctas',failed:'comprobaciones fallidas',blocked:'acceso bloqueado',stale:I18n.t('versión anterior'),skipped:I18n.t('sin comprobaciones')})[status] || status}
function checkpointDate(value){return new Date(value*1000).toLocaleString(I18n.locale,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}
function lastActivityAt(a){
 return Math.max(a.taskAt||0,a.terminalInputAt||0,a.responseAt||0,a.contextAt||0,a.goalUpdatedAt||0,a.stateAt||0,a.interactionAt||0);
}
function renderCheckpoints(){
 const section=$('#agent-checkpoints'),a=state.agents.find(a=>a.id===selected);
 section.hidden=!a||view!=='agent'||$('#agent-view').hidden;
 if(!checkpointStore||section.hidden)return;
 const rows=agentCheckpoints(a),latest=rows[0],currentQA=state.checkpointEvidence?.[a.id]||0;
 const pending=aiPending&&aiRequestedAgent===a.id,error=aiRequestedAgent===a.id?aiError:null;
 const stale=latest&&Math.max(lastActivityAt(a),currentQA)>(latest.capturedAt||latest.generatedAt);
 const button=$('#checkpoint-refresh'),freshness=$('#checkpoint-freshness'),status=$('#checkpoint-status');
 button.hidden=!!latest&&!stale&&!pending&&!error;
 button.disabled=!!aiPending;
 setMarkup(button,icon('refresh'));
 const refreshName=pending?I18n.t('Generando…'):error?I18n.t('Reintentar'):latest?I18n.t('Actualizar checkpoint'):I18n.t('Generar checkpoint');
 button.title=refreshName;button.setAttribute('aria-label',refreshName);
 button.classList.toggle('is-loading',!!pending);
 $('#checkpoint-consulted').textContent=latest?I18n.t('Último checkpoint · ')+checkpointDate(latest.generatedAt):I18n.t('Sin checkpoints');
 freshness.hidden=!latest;
 freshness.dataset.signal=stale?'waiting':'ready';
 setMarkup(freshness,latest?ht`${icon(stale?'attention':'check')}${stale?I18n.t('Hay actividad posterior a este checkpoint.'):I18n.t('Al día con la actividad registrada')}`:'');
 status.hidden=!error;status.textContent=error||'';section.setAttribute('aria-busy',String(!!pending));
 const signature=JSON.stringify([checkpointKey(a),rows,a.taskAt,currentQA,I18n.language]);if(signature===checkpointSignature)return;
 checkpointSignature=signature;
 const receipt=r=>ht`<article class="checkpoint-entry"><h3>${esc(r.headline)}</h3><p class="checkpoint-summary">${esc(r.summary)}</p>${r.changes.length?ht`<h4>Cambios principales</h4><ul>${r.changes.map(c=>ht`<li>${esc(c)}</li>`).join('')}</ul>`:''}${r.nextStep?ht`<div class="checkpoint-next"><strong>Siguiente paso</strong><p>${esc(r.nextStep)}</p></div>`:''}${r.evidence?.length?ht`<div class="checkpoint-verification">${r.evidence.map(e=>ht`<span>${e.status==='passed'&&e.revisionVerified&&e.finishedAt>0&&e.finishedAt>=(r===latest?Math.max(a.taskAt||0,currentQA):(r.taskAt||0))?I18n.t('Validado en el entorno'):I18n.t('Validación pendiente o anterior')} · ${esc(statusLabelSafe(e.status))}</span>`).join('')}</div>`:''}<footer>${esc(r.source)} · Contexto del ${esc(checkpointDate(r.capturedAt||r.generatedAt))}</footer></article>`;
 setMarkup($('#checkpoint-content'),latest?receipt(latest)+(rows.length>1?ht`<div class="checkpoint-history"><h3>Checkpoints anteriores <span>${rows.length-1}</span></h3>${rows.slice(1).map(r=>ht`<details><summary><time datetime="${esc(new Date(r.generatedAt*1000).toISOString())}">${esc(checkpointDate(r.generatedAt))}</time><span>${esc(r.headline)}</span></summary>${receipt(r)}</details>`).join('')}</div>`:''):ht('<div class="checkpoint-empty"><p>Genera un resumen del avance, los cambios y el siguiente paso.</p></div>'));
}
